-- Migration 0012: allow generated covers as a media kind.
--
-- ## Why a third kind rather than a flag on an existing row
--
-- The card's cover is chosen from `media_objects` (SPEC §15), and today that means the
-- first `body` image by position. An article with no body image therefore has no cover,
-- and 77 of the first 100 imported articles are in exactly that state. Generating one
-- gives those articles a cover, but the generated bytes are not a body image: they are
-- not part of the article's document, they are not positioned in the flow, and a re-parse
-- must never treat them as a figure the author inserted.
--
-- A separate `kind` says that in the schema, where the distinction can be enforced:
--
--   body    an image the article's document references, positioned in the flow
--   avatar  the author's profile picture, `position` 0
--   cover   a generated stand-in for a cover, owned by the app and not the article
--
-- ## Why the CHECK has to be rebuilt
--
-- SQLite has no `ALTER TABLE ... DROP CONSTRAINT`, so widening a CHECK means recreating
-- the table and copying it. That is what the sequence below does, and it is done inside
-- the migration's transaction so the table is never observably without its rows.
--
-- The `cover` row is stored `position` 0. It is not in the article flow, so position is
-- only carrying the `UNIQUE (article_id, kind, position)` guarantee — one generated cover
-- per article, which is what lets `generateCover` be idempotent.

PRAGMA foreign_keys = OFF;

CREATE TABLE media_objects_new (
  id TEXT PRIMARY KEY,
  article_id TEXT NOT NULL,

  position INTEGER NOT NULL,

  kind TEXT NOT NULL DEFAULT 'body' CHECK (kind IN ('body', 'avatar', 'cover')),

  source_url TEXT NOT NULL,

  r2_key TEXT,

  width INTEGER,
  height INTEGER,
  alt_text TEXT,

  status TEXT NOT NULL DEFAULT 'external_fallback'
    CHECK (status IN ('ready', 'failed', 'external_fallback')),

  content_type TEXT,
  byte_size INTEGER,

  error_code TEXT,
  error_message TEXT,

  attempt_count INTEGER NOT NULL DEFAULT 0,
  fetched_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,

  UNIQUE (article_id, source_url),
  UNIQUE (article_id, kind, position),

  FOREIGN KEY (article_id) REFERENCES articles (id) ON DELETE CASCADE
);

INSERT INTO media_objects_new SELECT
  id, article_id, position, kind, source_url, r2_key, width, height, alt_text,
  status, content_type, byte_size, error_code, error_message,
  attempt_count, fetched_at, created_at, updated_at
FROM media_objects;

DROP TABLE media_objects;
ALTER TABLE media_objects_new RENAME TO media_objects;

-- The three indexes from 0005, recreated with their original names and definitions so
-- nothing that planned against them loses its index. DROP TABLE removed them along with
-- the old table.
CREATE INDEX idx_media_article ON media_objects (article_id, position);
CREATE INDEX idx_media_status ON media_objects (status);
CREATE INDEX idx_media_pending ON media_objects (article_id) WHERE r2_key IS NULL;

PRAGMA foreign_keys = ON;
